import json,numpy as np
from PIL import Image

def comps(mask):
 h,w=mask.shape;seen=np.zeros_like(mask,bool);out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  stack=[(y,x)];seen[y,x]=1;pts=[]
  while stack:
   a,b=stack.pop();pts.append((a,b))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     yy,xx=a+dy,b+dx
     if 0<=yy<h and 0<=xx<w and mask[yy,xx] and not seen[yy,xx]:seen[yy,xx]=1;stack.append((yy,xx))
  if len(pts)>=5:
   a=np.array(pts);out.append((len(pts),a[:,1].mean(),a[:,0].mean(),a[:,1].min(),a[:,0].min(),a[:,1].max(),a[:,0].max()))
 return sorted(out,reverse=True)
for fn in ['orange_grasp_pose','grip_close','lift_check']:
