  R,G,B=im.transpose(2,0,1);mask=(R>G*1.3)&(G>B*1.15)&(R>65)&(R<190)&(G<155)&(B<115)
  print(cam,'comps',comps(mask)[:10])
  for area,u,v,x0,y0,x1,y1 in comps(mask)[:5]:
   c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);z=np.median(d[max(0,int(v)-2):int(v)+3,max(0,int(u)-2):int(u)+3]);p=T@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);print(' ',area,(u,v),'z',z,'world',p[:3])
